public static class Importer
{
    // Kept "for the status page": every batch stays reachable forever
    private static readonly List<List<OrderRow>> s_history = [];

    public static void Import(IEnumerable<OrderRow> rows)
    {
        List<OrderRow>? batch = rows.ToList();
        Save(batch);
        s_history.Add(batch);   // the real reason memory never comes back

        batch = null;           // changes nothing: s_history still holds it
        GC.Collect();           // a full blocking GC that frees nothing
    }

    static void Save(List<OrderRow> batch) { /* write to the database */ }
}

public static class Importer
{
    // The status page only needs a summary, not the rows
    public static ImportSummary? LastImport { get; private set; }

    public static void Import(IEnumerable<OrderRow> rows)
    {
        var batch = rows.ToList();
        Save(batch);
        LastImport = new(batch.Count, DateTimeOffset.UtcNow);
        // No null, no GC.Collect: once Import returns, nothing reaches
        // the batch, and a later collection reclaims it when space is needed
    }

    static void Save(List<OrderRow> batch) { /* write to the database */ }
}

public record ImportSummary(int Rows, DateTimeOffset At);
